-- Gen4Archives.lua -- NARC member name tables for Pokemon Platinum.
--
-- Generated from the .order files shipped with the pokeplatinum decompilation
-- project.  A NARC has no directory: members are addressed only by index, so
-- the .order files are the sole record of what each index actually is.  They
-- were matched to archives in the cartridge by member count.
--
-- No cartridge data is stored here.  These are names only; every byte still
-- comes from the user's own ROM at extraction time.
--
-- Why this matters: graphics archives interleave NCGR (tiles), NCLR (palette),
-- NSCR (tilemap), NCER (cells) and NANR (animation) with no positional rule,
-- so a screen cannot be composed by taking members in threes.  Members that
-- belong together share a base name, and that is what Gen4Archives.groups
-- recovers.

local Gen4Archives = {}

-- Archives whose members are a plain numbered run, stored as a pattern.
Gen4Archives.SEQUENTIAL = {
	["/data/arealight.narc"] = { prefix = "lighting_set_", width = 3, first = 0, suffix = "", count = 4 },
	["/fielddata/areadata/area_build_model/area_build.narc"] = { prefix = "prop_model_set_", width = 3, first = 0, suffix = "", count = 71 },
	["/fielddata/areadata/area_build_model/areabm_texset.narc"] = { prefix = "prop_texture_set_", width = 3, first = 0, suffix = ".nsbtx", count = 71 },
