Gen4Archives.DELIMITER = "|"

-- Unresolved on purpose.  Three .order files could not be tied to a single
-- archive: anim_ncer.order and anim_ncgr.order both match wecell.narc and
-- nothing distinguishes them by count, and species_icons.order has no archive
-- of its length in this cartridge.  Guessing would put wrong names on real
-- members, which is worse than having none.
Gen4Archives.UNRESOLVED = { "anim_ncer", "anim_ncgr", "species_icons" }

Gen4Archives.cache = {}

-- names(path) -> array of member names, or nil when the archive is unnamed.
-- Index i of the returned array is member i - 1 of the NARC (NARC members are
-- numbered from zero).
function Gen4Archives.names(path)
	local hit = Gen4Archives.cache[path]
	if hit ~= nil then
		if hit == false then return nil end
		return hit
	end

	local out
	local pattern = Gen4Archives.SEQUENTIAL[path]
	if pattern then
		out = {}
		local fmt = "%s%0" .. pattern.width .. "d%s"
		for i = 0, pattern.count - 1 do
			out[i + 1] = fmt:format(pattern.prefix, pattern.first + i, pattern.suffix)
		end
	else
		local packed = Gen4Archives.PACKED[path]
		if packed then
			out = {}
			local n = 0
			for piece in packed:gmatch("[^|]+") do
				n = n + 1
				out[n] = piece
			end
		end
	end

	Gen4Archives.cache[path] = out or false
	return out
end

-- name(path, member) -> the name of one member, or nil.
function Gen4Archives.name(path, member)
	local list = Gen4Archives.names(path)
	return list and list[member + 1] or nil
end

-- find(path, name) -> member index, or nil.  Matches the full name first, then
-- the base name, so "bag_sprite_male" finds "bag_sprite_male.NCGR".
function Gen4Archives.find(path, name)
	local list = Gen4Archives.names(path)
	if not list then return nil end
	for i = 1, #list do
		if list[i] == name then return i - 1 end
	end
	for i = 1, #list do
		if Gen4Archives.baseName(list[i]) == name then return i - 1 end
	end
	return nil
end

-- A trailing ".lz" is a storage detail, not a kind: "terrain_grass_player.NCGR.lz"
-- is an NCGR that happens to be LZ77-compressed.  Strip it before reading the
-- real extension, or every compressed member lands in a kind of its own and
-- stops grouping with the palette it belongs to.
local function withoutCompression(name)
	local stem = name:match("^(.*)%.[Ll][Zz]$")
	if stem then return stem, true end
	return name, false
end

-- baseName("terrain/grass/day.NCLR") -> "terrain/grass/day"
-- baseName("terrain_grass_player.NCGR.lz") -> "terrain_grass_player"
function Gen4Archives.baseName(name)
	local stem = withoutCompression(name)
	return (stem:gsub("%.[A-Za-z0-9]+$", ""))
end

-- extension("terrain/grass/day.NCLR") -> "NCLR" (upper case), or nil.
-- The ".lz" is reported separately by compressed(), not as the extension.
function Gen4Archives.extension(name)
	local stem = withoutCompression(name)
	local ext = stem:match("%.([A-Za-z0-9]+)$")
	return ext and ext:upper() or nil
end

-- compressed(name) -> true when the member is stored LZ77-compressed.
function Gen4Archives.compressed(name)
	local _, lz = withoutCompression(name)
	return lz
end

-- groups(path) -> array of { base, order, NCGR = i, NCLR = i, ... }
--
-- This is the point of the whole file.  Members that share a base name are the
-- parts of one image: tiles plus palette plus tilemap.  Grouping by name is
-- reliable where grouping by position is not -- archives mix lone palettes,
-- shared palettes and multi-tilemap sets freely.
function Gen4Archives.groups(path)
	local list = Gen4Archives.names(path)
	if not list then return nil end

	local byBase, out = {}, {}
	for i = 1, #list do
		local base = Gen4Archives.baseName(list[i])
		local group = byBase[base]
		if not group then
			group = { base = base, order = #out + 1 }
			byBase[base] = group
			out[#out + 1] = group
		end
		local ext = Gen4Archives.extension(list[i]) or "BIN"
		-- Keep the first of a repeated kind; later ones are alternates.
		if group[ext] == nil then
			group[ext] = i - 1
		else
			group[ext .. "_alt"] = group[ext .. "_alt"] or {}
			table.insert(group[ext .. "_alt"], i - 1)
		end
	end
	return out
end

-- cellBank(path, base) -> member index, the name it matched, and how sure that
-- match is.  nil when the archive holds nothing that could serve this sheet.
--
-- A cell bank is almost never named after the sheet it serves, because one
-- bank usually serves many sheets -- every terrain platform in the game shares
-- two banks, one per side, which is why all 24 platform sheets are exactly 128
-- tiles.  The spellings below are the ones the cartridge actually uses:
--
--   named   healthbox/short      -> healthbox/short_cell      (its own bank)
--   folder  type_icons/fire      -> type_icons/cell           (one per folder)
--   folder  ball_throws/poke     -> ball_throws/shared_cell   (a shared bank)
--   folder  terrain/grass/player -> terrain/player_cell       (leaf, not folder)
--   prefix  bag_sprite_male      -> bag_sprite_cell           (bank names a set)
--   sole    cheri                -> berry_cell                (one bank, many)
--
-- The terrain case is why this is a list rather than a rule: the bank is named
-- for the SIDE and the terrain is the folder in between, so nothing about the
-- sheet's own name predicts it.
--
-- The last two are weaker and are reported as such.  `prefix` is safe because
-- the bank names a set the sheet is a member of; `sole` is a judgement -- the
-- archive holds exactly one bank and this sheet has no other candidate -- and
-- the caller should record that it was a guess rather than present the result
-- as though the cartridge had said so.
function Gen4Archives.cellBank(path, base)
	local names = Gen4Archives.names(path)
	if not names then return nil end

	local folder, leaf = base:match("^(.*)/([^/]+)$")
	local outer = folder and folder:match("^([^/]+)/") or folder

	local exact = { base .. "_cell", base .. "/cell" }
	local byFolder = {}
	if folder then
		byFolder[#byFolder + 1] = folder .. "/cell"
		byFolder[#byFolder + 1] = folder .. "/shared_cell"
	end
	if outer and leaf then
		byFolder[#byFolder + 1] = outer .. "/" .. leaf .. "_cell"
		byFolder[#byFolder + 1] = outer .. "/cell"
		byFolder[#byFolder + 1] = outer .. "/shared_cell"
	end

	for _, name in ipairs(exact) do
		local at = Gen4Archives.find(path, name)
		if at then return at, name, "named" end
	end
	for _, name in ipairs(byFolder) do
		local at = Gen4Archives.find(path, name)
		if at then return at, name, "folder" end
	end

	-- Collect this archive's banks once, for the two loose rules.
	local banks = {}
	for i = 1, #names do
		if Gen4Archives.extension(names[i]) == "NCER" then
			banks[#banks + 1] = { at = i - 1, base = Gen4Archives.baseName(names[i]) }
		end
	end
	if #banks == 0 then return nil end

	-- prefix: a bank called "<set>_cell" serves "<set>_<member>".  Longest
	-- prefix wins, so a sheet does not attach to a shorter set that happens to
	-- share an opening word.
	local best, bestName
	for _, bank in ipairs(banks) do
		local set = bank.base:match("^(.*)_cell$")
		if set and #set > 0 and base:sub(1, #set + 1) == set .. "_" then
			if not bestName or #set > #bestName then
				best, bestName = bank, set
			end
		end
	end
	if best then return best.at, best.base, "prefix" end

	-- sole: one bank in the whole archive and nothing better to go on.
	if #banks == 1 then return banks[1].at, banks[1].base, "sole" end
	return nil
end

-- known(path) -> true when this archive has a name table at all.
function Gen4Archives.known(path)
	return (Gen4Archives.SEQUENTIAL[path] or Gen4Archives.PACKED[path]) ~= nil
end

-- paths() -> sorted array of every archive this table covers.
function Gen4Archives.paths()
	local out = {}
	for path in pairs(Gen4Archives.SEQUENTIAL) do out[#out + 1] = path end
	for path in pairs(Gen4Archives.PACKED) do out[#out + 1] = path end
	table.sort(out)
	return out
end

return Gen4Archives
